contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depAmt, uint outAmt) public payable {
        // Fund this test contract so it can send Ether to c.
        require(address(this).balance >= depAmt);

        uint balBeforeDeposit = c.balances(address(this));
        c.Deposit{value: depAmt}();
        uint balAfterDeposit = c.balances(address(this));

        // Make sure the CashOut is valid: outAmt <= the balance we just established.
        require(outAmt <= balAfterDeposit);

        uint contractBalBefore = address(c).balance;
        uint histLenBefore = c.TransferLog().History.length;

        bool reverted;
        try c.CashOut(outAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));
        uint contractBalAfter = address(c).balance;
        uint histLenAfter = c.TransferLog().History.length;

        assert(
            reverted ||
            (
                balBeforeDeposit == 0 &&
                balAfter == balAfterDeposit - outAmt &&
                contractBalAfter == contractBalBefore - outAmt &&
                histLenAfter == histLenBefore + 1
            )
        );
    }

    receive() external payable {}
}

