contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint depositAmount, uint cashOutAmount) public payable {
        require(depositAmount > c.MinDeposit(), "deposit too small");
        require(address(this).balance >= depositAmount, "not enough balance for deposit");

        bool depositSucceeded;
        try c.Deposit{value: depositAmount}() {
            depositSucceeded = true;
        } catch {
            depositSucceeded = false;
        }

        if (!depositSucceeded) {
            assert(c.balances(address(this)) == 0);
            return;
        }

        require(c.balances(address(this)) == depositAmount, "deposit not credited correctly");

        uint balanceBefore = c.balances(address(this));
        uint contractBalanceBefore = address(c).balance;
        uint testBalanceBefore = address(this).balance;

        bool cashOutSucceeded;
        try c.CashOut(cashOutAmount) {
            cashOutSucceeded = true;
        } catch {
            cashOutSucceeded = false;
        }

        if (cashOutSucceeded) {
            assert(cashOutAmount <= balanceBefore);
            assert(c.balances(address(this)) == balanceBefore - cashOutAmount);
            assert(address(c).balance == contractBalanceBefore - cashOutAmount);
            assert(address(this).balance == testBalanceBefore + cashOutAmount);
        } else {
            assert(c.balances(address(this)) == balanceBefore);
            assert(address(c).balance == contractBalanceBefore);
        }
    }
}

