import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C(address(new Log()));
    }

    function _run(uint256 depAmt, uint256 cashAmt) internal {
        depAmt = bound(depAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        uint256 minDep;
        try c.MinDeposit() returns (uint256 __r) { minDep = __r; } catch { return; }
        vm.assume(depAmt > minDep);
        vm.assume(address(this).balance >= depAmt);
        try c.Deposit{value: depAmt}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        vm.assume(cashAmt <= balBefore);
        bool reverted;
        try c.CashOut(cashAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        assertTrue(reverted || balAfter == balBefore - cashAmt);
    }

    function testFuzz_run(uint256 depAmt, uint256 cashAmt) public {
        _run(depAmt, cashAmt);
    }

    receive() external payable {}
}
